  INSERT INTO _n5_mnemonics_212 (character, mnemonic) VALUES
    ('先', 'Bayangkan dua kaki di bawah melangkah mengikuti penunjuk bercabang di atasnya. Orang yang membawa penunjuk itu bergerak lebih dahulu.'),
    ('生', 'Bayangkan sebatang tanaman hidup. Garis bawah menjadi tanah, garis tegak menjadi batang, dan garis-garis atas menjadi daun yang tumbuh.'),
    ('学', 'Bayangkan anak 子 belajar di bawah atap kecil. Tiga goresan di atasnya menjadi percikan ide saat ia memahami pelajaran.'),
    ('校', 'Bayangkan pohon 木 di kiri sebagai penanda halaman sekolah. Di kanan, seorang murid bertopi merentangkan tangan dan menyilangkan kaki sambil menunggu bel masuk.'),
    ('国', 'Bayangkan batu permata 玉 dilindungi tembok persegi di sekelilingnya. Seluruh wilayah di dalam tembok itu adalah sebuah negara.'),
    ('名', 'Bayangkan bentuk bulan sabit di atas mulut 口. Dalam gelap, mulut itu menyebutkan nama agar orang lain mengenalinya.'),
    ('人', 'Bayangkan seseorang berdiri dengan kedua kaki terbuka. Dua garis yang bertemu di atas membentuk seorang manusia.'),
    ('語', 'Bayangkan mulut 口 di kanan bawah mengucapkan lima 五 kata. Kata-katanya 言 berderet di kiri, membentuk sebuah bahasa.'),
    ('何', 'Bayangkan orang 亻 di kiri menatap mulut 口 di kanan yang dinaungi garis berkait. Ia kebingungan lalu bertanya, ''Apa?'''),
    ('魚', 'Bayangkan seekor ikan berdiri tegak. Kepala kecilnya berada di atas, tubuh berpetak di tengah, dan empat sirip pendek berjajar di bawah.'),
    ('本', 'Bayangkan pohon 木 dengan pangkal batang ditandai satu garis pendek. Kayu dari pohon itu dijadikan kertas untuk membuat buku.'),
    ('花', 'Bayangkan dua tunas 艹 di atas orang 亻 dan sendok berbentuk 匕. Ia menyiram tunas dengan sendok sampai tumbuh bunga.'),
    ('一', 'Bayangkan sebatang lidi diletakkan mendatar. Hanya ada satu lidi.'),
    ('二', 'Bayangkan dua batang lidi ditumpuk mendatar. Satu di atas dan satu di bawah, jumlahnya dua.'),
    ('三', 'Bayangkan tiga batang lidi ditumpuk mendatar. Hitung dari atas ke bawah: satu, dua, tiga.'),
    ('四', 'Bayangkan jendela dengan empat sudut. Dua tirai terlipat berada di dalam bingkainya, mengingatkanmu untuk menghitung keempat sudut itu.'),
    ('五', 'Bayangkan angka 5 dibuat kaku seperti rak. Bagian atas dan bawahnya mendatar, sedangkan bagian tengahnya berbelok untuk mengingatkanmu pada lima.'),
    ('六', 'Bayangkan orang bertopi lebar sedang berlari dengan kedua kaki terbuka. Ia terburu-buru berangkat tepat pukul enam.'),
    ('七', 'Bayangkan angka 7 berubah menjadi kait bertopi lebar. Garis mendatar menembus batangnya, lalu ujung bawahnya menekuk ke kanan.'),
    ('八', 'Bayangkan dua kaki membuka seperti pintu masuk. Di antara keduanya, delapan anak sedang mengantre untuk lewat.'),
    ('九', 'Bayangkan sembilan pelari melewati gerbang kecil. Tiang kirinya miring, sedangkan tiang kanan menekuk dan berkait ke luar.'),
    ('十', 'Bayangkan tanda tambah besar yang mempertemukan dua tangan. Masing-masing tangan punya lima jari, jadi jumlahnya sepuluh.'),
    ('安', 'Bayangkan perempuan 女 berteduh dengan tenang di bawah atap 宀. Penginapannya murah, jadi ia bisa beristirahat tanpa cemas.'),
    ('高', 'Bayangkan gedung bertingkat dengan atap di puncak, jendela kotak di tengah, dan pintu kotak di bawah. Gedungnya tinggi, harga kamarnya pun mahal.'),
    ('古', 'Bayangkan kotak 口 tua dengan tanda silang 十 di atasnya. Tanda yang sudah berkarat itu memperingatkan bahwa barang di dalamnya sangat kuno.'),
    ('新', 'Bayangkan kapak 斤 di kanan menebang pohon 木 di kiri bawah. Dari kayunya dibuat papan nama baru yang berdiri tegak seperti 立 di kiri atas.'),
    ('白', 'Bayangkan jendela berbentuk 日 tersorot seberkas cahaya dari kiri atas. Cahayanya begitu terang hingga seluruh jendela tampak putih.'),
    ('長', 'Bayangkan rambut dengan beberapa helai mendatar di atas. Rambut itu menjuntai panjang ke bawah, lalu ujungnya melengkung ke kanan.'),
    ('男', 'Bayangkan seorang laki-laki membawa papan kotak berpetak seperti 田. Di bawahnya, pegangan papan melengkung seperti 力.'),
    ('女', 'Bayangkan seorang perempuan menyilangkan kaki sambil merentangkan lengan. Garis lengkung dan garis silang membentuk posenya.'),
    ('気', 'Bayangkan embusan napas membentuk garis-garis di bagian atas. Di bawahnya ada pusaran kecil bersilang, seperti energi yang berputar di dalam tubuh.'),
    ('上', 'Bayangkan garis panjang di bawah sebagai lantai. Sebuah penunjuk berdiri di atasnya dengan lengan kecil mengarah ke kanan, mengajakmu melihat ke atas.'),
    ('下', 'Bayangkan garis panjang di atas sebagai langit-langit. Penunjuk yang menggantung darinya mengarahkan pandangan ke bawah.'),
    ('中', 'Bayangkan sebuah kotak ditembus garis tegak tepat di tengah. Garis itu menunjukkan bagian tengah di dalam kotak.'),
    ('外', 'Bayangkan bentuk bulan sabit di kiri, di samping tiang bercabang kecil di kanan. Tiang itu menjadi penunjuk jalan ke luar pada malam hari.'),
    ('左', 'Bayangkan tangan di atas memegang penggaris berbentuk 工 di bawahnya. Kamu memakainya dengan tangan kiri.'),
    ('右', 'Bayangkan tangan di atas menyuapkan makanan ke mulut 口 di bawahnya. Tangan yang dipakai adalah tangan kanan.'),
    ('前', 'Bayangkan sepasang lampu di atas garis mendatar. Di bawahnya, jendela berpetak di kiri dan dua wiper tegak di kanan menandai bagian depan kendaraan.'),
    ('後', 'Bayangkan langkah kecil di kiri, tali terpilin di kanan atas, dan kaki yang menyeret di kanan bawah. Orang itu tertinggal di belakang rombongan.'),
    ('間', 'Bayangkan sinar matahari 日 masuk di antara dua daun gerbang 門. Cahaya terlihat melalui celah di tengahnya.'),
    ('車', 'Bayangkan kendaraan dengan badan kotak berpetak di tengah. Sebuah batang menembusnya dari atas ke bawah, dengan poros melintang di kedua ujung.'),
    ('東', 'Bayangkan matahari 日 muncul di tengah pohon 木. Pagi dimulai saat matahari terbit dari timur.'),
    ('西', 'Bayangkan jendela kotak dengan dua tirai terlipat di dalamnya dan garis atap di atas. Dari jendela yang menghadap barat itu, kamu melihat matahari terbenam.'),
    ('南', 'Bayangkan kompas dengan pegangan berbentuk silang di atas. Bingkai di bawahnya berisi dua titik kecil dan jarum berpalang yang menunjuk ke selatan.'),
    ('北', 'Bayangkan dua orang berdiri saling membelakangi, satu menghadap kiri dan satu menghadap kanan. Mereka sedang menahan angin dingin yang datang dari utara.'),
    ('道', 'Bayangkan kepala 首 melihat ke depan, ditemani jalur berkelok 辶 di kiri dan bawahnya. Ikuti jalur itu sebagai jalanmu.'),
    ('駅', 'Bayangkan kuda 馬 menunggu di kiri, di samping papan peron yang kakinya melebar ke kanan. Itulah tempat penumpang berkumpul, sebuah stasiun.'),
    ('行', 'Bayangkan jejak langkah di kiri menuju palang penunjuk di kanan. Ikuti arah penunjuk itu dan mulailah berjalan.'),
    ('電', 'Bayangkan hujan 雨 turun di atas panel kotak berpetak. Dari panel itu menjulur kabel melengkung ke kanan, menyalurkan listrik.'),
    ('見', 'Bayangkan mata 目 yang memiliki dua kaki di bawahnya. Mata itu berjalan mendekat agar bisa melihat dengan jelas.'),
    ('読', 'Bayangkan kata-kata 言 di kiri dipasang pada kios di kanan. Kios bertanda tambah di atas dan berkaki dua itu mengundangmu membaca pengumumannya.'),
    ('書', 'Bayangkan kuas tegak menembus deretan garis mendatar di bagian atas. Di bawahnya ada halaman kotak bergaris, tempatmu menulis.'),
    ('年', 'Bayangkan kalender tahunan bertiang panjang di tengah dan beberapa garis mendatar untuk menandai musim. Goresan miring kecil di kiri atas menandai awal tahun.'),
    ('百', 'Bayangkan kotak putih 白 dengan garis tambahan sebagai tutup di atasnya. Pada tutup itu tertulis ''100'', karena isinya seratus koin.'),
    ('午', 'Bayangkan dua palang mendatar ditembus tiang tegak, dengan ujung miring kecil di kiri atas. Tiang itu menjadi jam matahari yang menandakan tengah hari.'),
    ('半', 'Bayangkan dua potongan kecil di atas tumpukan dua garis. Satu garis tegak membelah tumpukan tepat di tengah, membaginya menjadi setengah.'),
    ('週', 'Bayangkan jalur 辶 mengelilingi papan jadwal berbentuk kotak di kanan. Garis-garis dan kotak kecil di dalamnya menandai kegiatan yang berulang setiap minggu.'),
    ('万', 'Bayangkan satu garis mendatar menjadi meja bank. Dua kaki di bawahnya, satu miring dan satu berkait, menyangga uang sebanyak sepuluh ribu.'),
    ('千', 'Bayangkan seribu batang lidi diikat pada tiang berbentuk 十. Ujung ikatannya terlihat sebagai garis miring pendek di bagian atas.'),
    ('毎', 'Bayangkan papan kotak bergaris di bawah dua goresan kecil di atas. Papan itu adalah jadwal yang kamu buka setiap hari.'),
    ('食', 'Bayangkan tudung saji di bagian atas 食 menutupi wadah di bawahnya. Saat tudung dibuka, ada makanan yang siap kamu makan.'),
    ('飲', 'Bayangkan bagian kiri 飲 sebagai makanan di meja, dan 欠 di kanan sebagai orang yang membuka mulut. Setelah makan, ia meneguk air untuk minum.'),
    ('立', 'Bayangkan bagian atas 立 sebagai kepala dan bahu seseorang, dengan dua kaki di bawahnya. Kedua kakinya berpijak pada garis tanah: ia sedang berdiri.'),
    ('休', 'Bayangkan orang 亻 di kiri bersandar pada pohon 木 di kanan setelah berjalan jauh. Ia sedang beristirahat.'),
    ('入', 'Bayangkan dua garis 入 sebagai sisi pintu tenda yang terbuka di bawah. Kamu melewati celah itu untuk masuk ke tenda.'),
    ('出', 'Bayangkan garis tegak 出 sebagai tunas yang menembus dua lapis tanah berbentuk 凵. Ujung tunas itu akhirnya keluar ke permukaan.'),
    ('言', 'Bayangkan 口 di bawah 言 sebagai mulut yang berbicara. Garis-garis di atasnya adalah kata-kata yang keluar saat seseorang berkata sesuatu.'),
    ('話', 'Bayangkan kata-kata 言 di kiri keluar saat lidah 舌 di kanan bergerak. Kamu sedang berbicara untuk menceritakan sesuatu.'),
    ('聞', 'Bayangkan telinga 耳 di tengah gerbang 門. Seseorang menempelkan telinganya di sana untuk mendengar percakapan dari balik gerbang.'),
    ('買', 'Bayangkan jaring 罒 di atas 買 menampung kerang 貝 di bawahnya. Kamu membawa kerang itu sebagai uang untuk membeli barang.'),
    ('店', 'Bayangkan atap 广 menaungi papan ramalan 占. Di bawah atap itu, seorang peramal membuka toko kecilnya.'),
    ('円', 'Bayangkan bingkai luar 円 sebagai loket penukaran uang, dengan sekat di dalamnya. Di loket itu, kamu menukar uang dengan koin yen yang bulat.'),
    ('会', 'Bayangkan bagian atas 会 sebagai atap tempat orang berteduh. Bentuk 云 di bawahnya menjadi meja tempat mereka duduk dan bertemu.'),
    ('社', 'Bayangkan 礻di kiri sebagai papan nama dan 土 di kanan sebagai tanah tempat sebuah kantor dibangun. Papan itu menunjukkan nama perusahaan pemilik kantor.'),
    ('日', 'Bayangkan bingkai 日 sebagai matahari kotak, dengan garis cahaya di tengahnya. Saat matahari itu terbit lagi, satu hari baru dimulai.'),
    ('月', 'Bayangkan sisi melengkung 月 sebagai bulan sabit. Dua garis di dalamnya menjadi garis bayangan pada permukaan bulan.'),
    ('火', 'Bayangkan dua garis tengah 火 sebagai nyala api yang menjulang. Dua garis kecil di sisinya menjadi percikan api yang beterbangan.'),
    ('水', 'Bayangkan garis tengah 水 sebagai aliran air utama. Garis-garis di kiri dan kanannya menjadi percikan air yang menyebar.'),
    ('木', 'Bayangkan garis tegak 木 sebagai batang pohon, garis mendatar sebagai cabangnya, dan dua garis miring sebagai akarnya. Itulah pohon yang tumbuh di depanmu.'),
    ('金', 'Bayangkan atap 金 menaungi tambang bertingkat tiga, dengan tiang tegak di tengah. Dua titik di kiri dan kanannya adalah butir emas yang akan dijadikan uang logam.'),
    ('土', 'Bayangkan garis tegak 土 sebagai patok yang tertancap di tanah. Garis pendek menandai gundukan di sekitarnya, dan garis panjang di bawah menjadi permukaan tanah.'),
    ('時', 'Bayangkan matahari 日 di kiri menyinari kuil 寺 di kanan. Kamu melihat jam di kuil itu untuk mengetahui waktu.'),
    ('分', 'Bayangkan pisau 刀 di bawah 分 membelah sesuatu menjadi dua bagian yang membuka seperti 八 di atasnya. Satu jam pun bisa dibagi menjadi bagian-bagian kecil bernama menit.'),
    ('子', 'Bayangkan lengkungan atas 子 sebagai kepala anak. Garis mendatar menjadi dua lengannya yang terbuka, dan garis turun menjadi tubuhnya saat ia meminta dipeluk.'),
    ('父', 'Bayangkan dua garis pendek di atas 父 sebagai alis ayah. Dua garis panjang yang bersilang di bawahnya menjadi kedua lengannya saat ayah menyilangkan tangan.'),
    ('母', 'Bayangkan bingkai 母 sebagai tubuh ibu, dengan garis melintang sebagai sabuk bajunya. Dua titik di dalamnya menjadi dua kancing baju ibu saat ia memelukmu.'),
    ('友', 'Bayangkan garis miring dari bagian atas 友 sebagai lengan yang terulur. Bentuk 又 di bawahnya menjadi tangan teman yang menyambut untuk bersalaman.'),
    ('手', 'Bayangkan garis-garis melintang 手 sebagai jari-jari yang terbuka. Garis panjang berkait di tengah menjadi pergelangan tanganmu.'),
    ('足', 'Bayangkan kotak di atas 足 sebagai lutut dan bagian bawahnya sebagai tungkai dengan telapak yang menapak ke kanan. Itulah kaki yang siap melangkah.'),
    ('口', 'Bayangkan kotak 口 sebagai mulut yang terbuka lebar saat kamu berkata a. Lihat ruang kosong di tengah mulut itu.'),
    ('目', 'Bayangkan bingkai 目 sebagai mata yang diputar tegak. Dua garis di dalamnya membatasi bagian tengah tempat pupil mata berada.'),
    ('耳', 'Bayangkan sisi panjang 耳 sebagai tepi telinga, dan garis-garis di dalamnya sebagai lipatan telinga. Dekatkan telinga itu untuk mendengar bisikan.'),
    ('大', 'Bayangkan orang 大 merentangkan kedua tangan dan kakinya selebar mungkin. Ia ingin menunjukkan sesuatu yang sangat besar.'),
    ('小', 'Bayangkan garis tengah 小 sebagai tubuh anak kecil. Dua garis pendek di sisinya menjadi tangan mungil yang belum bisa merentang jauh.'),
    ('多', 'Bayangkan dua potong melon berbentuk 夕 ditumpuk, satu di atas yang lain. Kamu terus menambah potongan sampai ada banyak melon.'),
    ('少', 'Bayangkan 小 sebagai beberapa butir beras kecil, lalu garis miring di bawahnya sebagai sendok. Sendok itu hanya mendapat sedikit beras.'),
    ('雨', 'Bayangkan garis paling atas 雨 sebagai awan, lalu bingkai di bawahnya sebagai jendela dengan sekat tegak di tengah. Empat titik di dalam jendela menjadi tetes hujan yang turun.'),
    ('天', 'Bayangkan orang 大 berdiri dengan tangan terbuka. Garis mendatar di atas kepalanya adalah langit yang membentang tinggi.'),
    ('空', 'Bayangkan lubang 穴 di atas 空 sebagai jendela loteng, dan 工 di bawahnya sebagai penyangga. Melalui jendela kosong itu, kamu melihat langit luas.'),
    ('山', 'Bayangkan tiga garis tegak 山 sebagai tiga puncak gunung yang terhubung di bawah. Puncak di tengah menjulang paling tinggi.'),
    ('川', 'Bayangkan tiga garis 川 sebagai aliran sungai yang bergerak berdampingan. Ikuti arusnya dari atas ke bawah.'),
    ('来', 'Bayangkan 来 sebagai pohon kecil dengan dua buah di kiri dan kanan batangnya. Dua akar di bawah berubah menjadi kaki, lalu pohon itu datang menghampirimu.'),
    ('令', 'Bayangkan bagian atas 令 sebagai atap runcing. Bentuk bersudut di bawahnya menjadi orang yang menunduk, siap menerima perintah.');
  INSERT INTO n5_kanji_mnemonic_backup_212 (kanji_id, mnemonic)
